G3 = [
dict(id='PD3B-036', order=1, topic='推理结构相似', key='GD2022X-73',
 stem='农业得到极大发展后，农民的收入水平会显著提高，农业科技水平相对落后的地区农民收入水平不能提高。由此可知，农业科技水平相对落后的地区，农业产业有待发展。\n下列选项的逻辑结构与题干最相似的是：',
 options={'A': '气温低于10摄氏度时，某地的滑雪场就会对外开放。每年的国庆节当地的滑雪场都不对外开放。因此，每年国庆节当地气温都在10摄氏度及以上', 'B': '景无月不美，酒缺月无味。因此，只有赏月时，才能欣赏到美景、品尝到美味', 'C': '教育水平不高的地区，往往缺乏优秀的农业生产人才。乡村振兴需要大量的农业生产人才。因此。教育水平不高的地区较难实现乡村振兴', 'D': '人在逆境中要不忘初心，才能迎难而上，克服挑战；在顺境中也要不忘初心，才能戒骄戒躁，稳步前行，因此，人在任何处境下都要做到不忘初心'},
 src='A', chk='A', diff='M',
 sol='题干：a（农业极大发展）→b（收入显著提高）；c（科技落后地区）→¬b；所以c→¬a（“有待发展”即尚未极大发展）。形式：X→Y；Z→¬Y ⊢ Z→¬X，有效（由第二前提与第一前提的逆否传递）。\nA：气温低于10℃→滑雪场开放；国庆→不开放；所以国庆→气温在10℃及以上。第一前提为条件，第二前提否定其后件，结论否定前件，与题干逐项同形，当选。\nB：无月→景不美，缺月→酒无味；所以（美景且美味）→赏月。是“同一前件分别否定两个后件，再合并逆推”，结构不同。\nC：教育不高→（往往）缺人才；振兴→需人才；所以教育不高→较难振兴。逆否后形式上也能成立，但否定落在第一前提、两前提顺序与题干相反，且“往往……较难”是或然判断；不如A与题干逐项对应。\nD：两个不同的条件关系合成“任何处境都要不忘初心”，前提与结论的概念对不上。\n程序核验：按“前提顺序＋肯否位置”签名比对，唯一与题干同形的是A（verify_structure.log）。\n提速：先标“→”与“¬”的位置，再比前提顺序和“必然/或然”。',
 val='条件推理同形比对：A与题干“X→Y；Z→¬Y⊢Z→¬X”逐项一致；C逆否后也成立但顺序相反且为或然判断，练按顺序和模态比到底。',
 flags=['原卷错字照录', '版本取舍'],
 notes='解析原文（第38页）：题干“a→b，c→¬b，因此c→¬a”，A同形当选；解析把C写作“a→b，c→b，因此a→c”。编者认为C中“缺乏人才”与“需要人才”正负相反，实为同一有效式的换序、或然版本，与题干不如A贴合，答案同为A（定性与解析不同）。版本：xing-ce1 版D项作“戒骄成躁”，xingce 网友回忆版作“戒骄戒躁”，按后者；C项“因此。”两版相同，照录。编者难度估计：中。'),

dict(id='PD3B-037', order=2, topic='论证方式相似', key='JS2023A-101',
 stem='小朱：外星人一定存在\n小李：没有任何有关外星人存在的证据，所以外星人一定不存在\n以下哪项中乙的论证方式与小李最为相似？',
 options={'A': '甲：明天可能下雨\n乙：现在的天气状况特别好，所以明天很可能不下雨', 'B': '甲：老王一家今天应该都外出散步了\n乙：我一直没看到他们出去，所以老王一家应该都没有外出散步', 'C': '甲：老赵有时聪明\n乙：我只见过老赵不聪明的时候，所以老赵有时不聪明', 'D': '甲：小徐一定能晋级\n乙：目前小徐在积分榜上排名靠后，所以小徐可能不会晋级'},
 src='B', chk='B', diff='M',
 sol='小李的论证：没有任何证据证明外星人存在，所以外星人一定不存在——以“缺乏证明P的证据”推出“非P”（诉诸无知）。\nA：乙用“天气状况特别好”这一正面证据推“明天很可能不下雨”，是依据证据的或然推理，不是诉诸无知。\nB：乙以“一直没看到他们出去”（没有外出的证据）推“应该都没有外出散步”——同样以“没看到/没证据”推出否定结论，当选。\nC：乙见过老赵不聪明的时候，推“老赵有时不聪明”——有实例为据，结论成立，是有效推理。\nD：乙依据“排名靠后”推“可能不会晋级”，有正面依据。\n提速：只看乙的理由是“没看到/没有证据”还是“看到了某个事实”。',
 val='诉诸无知：“没有证据证明P→非P”，B“没看到出门→没出门”同构；A、D有正面依据，C由实例得“有时”是有效推理。',
 flags=[],
 notes='解析原文（第56页）：“题干的论证结构为：小李是通过说明小朱的观点没有证据，从而反驳了小朱的观点”，B“说明甲的观点没有证据，从而反驳甲的观点，与题干论证结构一致”。与编者一致（编者用“诉诸无知”命名，实质相同）。原卷对话句末无标点，照录。xingce 版文件（文件名未标回忆版）。编者难度估计：中。'),

dict(id='PD3B-038', order=3, topic='推理结构相似', key='GDXD2020SW-11',
 stem='城市比乡村人口密度更高，而高人口密度会导致犯罪率的上升，因此城市比乡村有着更高的犯罪率。\n下列选项中，与上述推理结构最为相似的是（　）。',
 options={'A': '酶是一种蛋白质，而蛋白质是由氨基酸组成的，因此酶也是由氨基酸组成的', 'B': '县比市辖区拥有更高的自主权，而更高的自主权会带来更高的审批效率，因此县比市辖区的审批效率更高', 'C': '猫科动物拥有敏锐的听力，老虎、猎豹和家猫都属于猫科动物，因此它们的听力都很敏锐', 'D': '相比农村的孩子，城市的孩子能够接触到更加优质的教育资源，同时城市的孩子升学率更高，因此优质的教育资源会提高升学率'},
 src='B', chk='B', diff='E',
 sol='题干：城市比乡村人口密度高（甲的C高于乙）；高人口密度导致犯罪率上升（C越高D越高）；所以城市犯罪率高于乡村（甲的D高于乙）。形式：比较＋单调因果 ⊢ 比较。\nA：酶是蛋白质，蛋白质由氨基酸组成，所以酶由氨基酸组成——类属传递，不含比较。\nB：县比市辖区自主权高；自主权越高审批效率越高；所以县的审批效率更高——与题干完全同形，当选。\nC：猫科动物听力敏锐，老虎等属猫科，所以它们听力敏锐——由一般到个别。\nD：城市孩子教育资源更好，同时升学率更高，所以优质资源提高升学率——由两个比较推因果，方向与题干相反，且是“伴随→因果”的无效推理。\n程序核验：题干/B在单调模型下全部成立；D存在反例（verify_structure.log）。\n提速：题干结论是比较句时，先排除结论不是比较的选项，再看因果方向。',
 val='比较＋单调因果⊢比较；D把伴随当因果且方向相反，A、C是类属推理。',
 flags=[],
 notes='解析原文（第3页）：“题干的推理形式为：A比B的C高，C越高导致D越高，所以A比B的D高”，B当选；D“A比B的C高，同时A比B的D高，所以C越高导致D越高，与题干推理形式不同”。与编者一致。题干原卷跨第2—3页。编者难度估计：易（组内节奏题）。'),

dict(id='PD3B-039', order=4, topic='逻辑错误相似', key='GK2019F-113',
 stem='有位青年到杂志社询问投稿结果。编辑说：“你的稿子我看过了，总的来说有一些基础，不过在语言表达上仍不够成熟，流于幼稚。”青年问：“那能不能把它当作儿童文学作品呢？”\n下列选项中与青年所犯的逻辑错误相同的是：',
 options={'A': '甲到处宣扬说：“我从来不炫耀自己的优点。”', 'B': '甲说：“人生太短暂，我们应该珍惜时间，抓住机会，尽情挥霍。”', 'C': '甲问：“我能用蓝笔墨水写出红字，你信吗？”乙答：“不信。”甲就提笔在纸上写了一个“红”字', 'D': '甲开车撞到了行人乙，二人争执起来，甲说：“我有多年驾驶经验，责任不可能在我。”'},
 src='C', chk='C', diff='M',
 sol='青年的错误：编辑说稿子“流于幼稚”（语言表达不成熟），青年理解成“适合儿童”（儿童化）——同一个词前后意思不同，属偷换概念。\nA：说“从不炫耀优点”却到处宣扬——言行自相矛盾。\nB：主张珍惜时间，却说要尽情挥霍——自相矛盾。\nC：“红字”本指红颜色的字，甲却写了一个“红”字——同一词语前后指称不同，偷换概念，当选。\nD：以多年驾驶经验推出这次责任不在自己——以经验代替事实，是不当推论，不是偷换概念。\n提速：先给题干错误命名，再在选项中找“同一个词被换了意思”的那项。',
 val='逻辑错误命名后再比对：“幼稚”两义→偷换概念，C“红字”同类；A、B自相矛盾，D以经验代事实。',
 flags=[],
 notes='解析原文（第25页）：“题干的逻辑错误在于，将幼稚的理解方式由缺乏经验不成熟偷换成了年纪小天真，属于偷换概念”，C当选，A、B自相矛盾，D不属于偷换概念。与编者一致。编者难度估计：中。'),

dict(id='PD3B-040', order=5, topic='推理结构相似', key='GD2022X-70',
 stem='世界科技强国必须能够在全球范围内吸引人才、留住人才、用好人才。我国要建设世界科技强国。因此，我国必须注重对国际人才的吸引与使用。\n下列选项的逻辑结构与题干最相似的是：',
 options={'A': '人才的培养培育离不开良好的环境。因此，构筑集聚全球优秀人才的科研创新高地，完善配套制度，就能面向世界汇聚一流人才', 'B': '国家科技创新力的根本源泉在于人才，国家、民族长远发展离不开科技创新力。因此，培养创新型人才是国家、民族的长远发展之计', 'C': '科技创新离不开科技人员持久的时间和精力投入。因此，要建立让科研人员把主要精力放在科研上的保障机制', 'D': '榜样的力量对科技工作者来说是无穷的。两院院士是科技成果的主要贡献者，更应做好表率，激励广大科技工作者不断攻坚克难、勇攀高峰'},
 src='B', chk='B', diff='H',
 sol='题干：世界科技强国→必须引才、留才、用才（1→2）；我国要建设世界科技强国（我国→1，记作3→1）；所以我国必须注重国际人才的吸引与使用（3→2）。形式：1→2，3→1 ⊢ 3→2（传递，有效）。\nA：人才培养离不开良好环境（培养→环境）；所以构筑高地、完善制度（营造环境）“就能”汇聚一流人才——把必要条件当充分条件，形式不同。\nB：创新力的根本源泉在于人才（创新力→人才，1→2）；长远发展离不开创新力（发展→创新力，3→1）；所以培养人才是长远发展之计（3→2）——与题干同形，当选。\nC：科技创新离不开投入（1→2）；所以要建立保障机制——只有一个前提，结论出现新概念，形式不同。\nD：榜样对“科技工作者”力量无穷；院士是“科技成果的主要贡献者”——两个概念不同，链条接不上。\n程序核验：题干与B签名相同，A、C、D不同（verify_structure.log）。\n提速：把“我国要建设S”读成“我国→S”，题干就是三段链；选项中找两条首尾相接的“离不开/在于”。',
 val='把“我国要建设强国”读成“我国→强国”后成三段链，练识别隐含的链式结构；A把“离不开”当“就能”。',
 flags=[],
 notes='解析原文（第35—36页）：“题干的论证过程为：1→2，3→1，因此3→2”，B同形当选；A“1→2，因此2→3”，C“1→2，因此3”，D“两个不同的概念，不能进行串联”。与编者一致（文字层箭头缺失，据上下文复原）。xingce 网友回忆版与本版逐字一致（标点除外）。编者难度估计：难。'),

dict(id='PD3B-041', order=6, topic='对话方式相似', key='JS2022A-102',
 stem='甲：这本小说太精彩了，你喜欢里面的哪个角色呢？\n乙：我对小说不感兴趣，没有读过这本小说\n以下哪项的对话与上述对话最为相似？',
 options={'A': '教师：你不努力学习以后怎么能考上理想的大学呢？\n学生：我理想的大学太难考了，再努力也不一定能考上', 'B': '员工甲：总经理的讲话中，你认可哪些呢？\n员工乙：总经理的讲话我都赞成，我会尽全力执行讲话中的要求', 'C': '孩子：爸爸，夏天游泳更能锻炼身体呢，还是冬天游泳更能锻炼身体呢？\n父亲：游泳是非常好的锻炼方式，在任何时候游泳都能锻炼人', 'D': '商户：您上个月在我们商店购买的冰箱好用吗？\n顾客：你可能记错了，我上个月在你们店购买的是洗衣机'},
 src='D', chk='D', diff='M',
 sol='题干：甲问“你喜欢里面哪个角色”，这一问预设了“乙读过这本小说”；乙答“没有读过”，否定的是问题的预设，而不是对问题作答。\nA：教师的话预设学生想考理想大学，学生答“再努力也不一定能考上”——没有否定预设，只是回应“努力→考上”的关系。\nB：员工甲问“认可哪些”，乙答“都赞成”——接受预设，直接作答。\nC：孩子问“夏天还是冬天游泳更锻炼”，父亲答“任何时候都能锻炼”——回避比较，但没有否定“游泳能锻炼”这一预设。\nD：商户问“上个月买的冰箱好用吗”，预设顾客买了冰箱；顾客答“买的是洗衣机”——否定问题的预设，当选。\n提速：先找提问里“默认成立的事”，再看回答是在作答，还是在否定这件默认的事。',
 val='对话题：乙否定的是提问的预设（读过小说）而非作答，D同构；B、C接受预设作答，A回应条件关系。',
 flags=[],
 notes='解析原文（第33页“102.解析”）：“乙说自己对小说不感兴趣根本没读过，属于否定了甲所提问题的预设”，D当选，A、B、C均未否定预设。与编者一致。原卷乙的答句末无标点，照录。xingce 版文件（文件名未标回忆版）。编者难度估计：中。'),

dict(id='PD3B-042', order=7, topic='推理结构相似', key='GDXD2019SW-38',
 stem='市场的力量是有限的，仅仅依靠市场，并不能生产出优质的知识产品。可以说，想要生产出优质的知识产品，还必须依靠非市场力量加大对科研的投入。\n以下与上述推理在结构上最为相似的是（　）。',
 options={'A': '计算机专业的学生不一定会修电脑。其他专业的学生也可能会修电脑', 'B': '只是加强锻炼还无法拥有健康的体魄。想拥有健康体魄就不能仅靠锻炼', 'C': '如果只吃肉类，就不能膳食均衡。因此，想要达到膳食均衡就不能吃肉', 'D': '如果只注重智育，学生就无法全面发展。所以有必要对德育、体育等其他方面的教育加强重视'},
 src='D', chk='D', diff='H',
 sol='题干：仅靠市场（有市场、无非市场投入）不能生产优质知识产品；所以要生产优质知识产品，还必须依靠非市场力量加大投入。形式：（X且非Y）→非Q ⊢ Q→Y——结论点出需要补充的因素Y（在X既定在场时有效）。\nA：计算机专业学生不一定会修电脑，其他专业也可能会——不是条件推理，形式不同。\nB：只锻炼无法拥有健康体魄；想健康就不能仅靠锻炼——结论“健康→不能仅靠锻炼”只是把前提换个说法（逆否复述），没有点出要补充的因素。\nC：只吃肉不能膳食均衡；所以想均衡就不能吃肉——把“不能只吃”推成“不能吃”，推理错误。\nD：只注重智育，学生就无法全面发展；所以有必要加强德育、体育等其他方面——结论点出补充因素，与题干同形，当选。\n程序核验：题干与D在“X既定在场”背景下有效；B为前提的逆否复述；C无效（verify_structure.log）。\n提速：比结论的写法——题干结论里出现了“另一样东西”（非市场力量），选项结论也须出现“另一样东西”。',
 val='“仅靠X不能Q⊢要Q还须Y”：结论须点出补充因素；B只是把前提逆否复述，C把“不能只吃”推成“不能吃”。',
 flags=[],
 notes='解析原文（第10页）：“只靠市场→-知识产品；得出：知识产品→科研投入”，D“只注重智育→-全面发展；得出：全面发展→重视其他方面，与题干推理形式相同，当选”；B“健康体魄→-只锻炼，与题干推理形式不同”。与编者一致。题干原卷跨第7—8页。编者难度估计：难。'),

dict(id='PD3B-043', order=8, topic='归纳推出', key='GK2015D-101',
 stem='在防治癌症方面，橙汁有多种潜在的积极作用，尤其由于它富含橙皮素和柚苷素等类黄酮抗氧化剂。研究证据已经表明，橙汁可以减少儿童患白血病的风险，并有助于预防乳腺癌、肝癌和结肠癌。根据研究结果，橙汁的生物效应在很大程度上受到其成分的影响，而其成分的变化又依赖于气候、土壤、水果成熟度以及采摘后的存储方法等条件。\n由此可以推出：',
 options={'A': '并非所有的橙汁都有相同的防癌功效', 'B': '过度饮用橙汁会给身体健康造成不良影响', 'C': '相对于健康儿童而言，白血病患儿的橙汁饮用量较小', 'D': '生长于良好的气候土壤条件下，成熟并避光保存的橙子最有功效'},
 src='A', chk='A', diff='M',
 sol='题干信息：橙汁有多种潜在防癌作用，可减少儿童患白血病风险、有助于预防乳腺癌等；橙汁的生物效应在很大程度上受成分影响，成分又依赖气候、土壤、成熟度、采后存储等条件。\nA：并非所有橙汁都有相同的防癌功效——成分随条件变化、效应受成分影响，不同橙汁功效可以不同，“并非所有都相同”是稳妥推论，当选。\nB：过度饮用有害——题干未涉及饮用量，无中生有。\nC：白血病患儿橙汁饮用量较小——题干只说橙汁可减少风险，推不出患儿的实际饮用量。\nD：良好气候土壤、成熟并避光保存的橙子“最”有功效——题干只说受这些条件影响，没说哪种条件最好，“避光”也未提及，过度推断。\n提速：归纳推出优先选“并非所有/可能/有的”这类弱化结论；带“最、一定”或题干没提过的细节先排除。',
 val='归纳推出的稳妥度：“并非所有……相同”由“成分随条件变化”直接可得；D“最有功效”及“避光”属过度推断。',
 flags=['老卷（2013—2016年度）'],
 notes='解析原文（第11—12页）：“D项属于过度推断；A项‘并非所有的橙汁都有相同的防癌功效’……正好对应文段最后一句受多方面影响”。与编者一致。老卷选用理由：非形式归纳推出近年广东卷几乎不考，题源少且争议多（第2轮已隔离GD2021X-62），本题答案稳、陷阱典型（量词与无中生有）。同题见GK2015F-106（已一并锁定）。编者难度估计：中。'),

dict(id='PD3B-044', order=9, topic='论证过程相似', key='GD2019X-57', ans_page=10,
 stem='过分密集的城市布局不仅容易使城市产生热岛效应，也不符合生态美学的要求。因此，城市建设应该尽可能拉开布局，合理地间隔各城市组团，使城市看起来舒缓有序，不拥挤、不杂乱。\n以下和该论述过程的逻辑最为类似的是（　）。',
 options={'A': '只有有趣的故事和通俗的理论相结合，才能吸引人，让人真正理解其中的内涵，爱上科学。所以，从日常生活中的小事入手，科普也可以很有趣', 'B': '中小学课业负担太重，是影响中小学生快乐健康成长的大问题。所以，要将课业减负进行到底，扫除线上培训等减负盲区', 'C': '天文学的起源与文明的起源大致处于同一时期。因此，追寻天文学的起源也就意味着我们可以在某种程度上把握文明诞生和发展的脉络', 'D': '律师队伍事关群众对法治的需求，也与一个地方的竞争力直接相关。所以，完善的法律服务是营商环境的重要内容，也是衡量城市吸引力的重要标尺'},
 src='B', chk='B', diff='M',
 sol='题干：过分密集的城市布局会产生热岛效应、不符合生态美学（负面现象及其危害）；所以城市建设应拉开布局（针对该现象提出对策）。结构：负面现象→危害→对策。\nA：用“只有……才能……”讲科普要有趣的条件，结论“从小事入手科普也可以有趣”，没有负面现象及危害，结构不同。\nB：课业负担太重，是影响中小学生成长的大问题（负面现象及危害）；所以要减负到底（对策）——同构，当选。\nC：天文学起源与文明起源同期，所以追寻前者可把握后者——由同时性推意义，无问题与对策。\nD：律师队伍事关法治需求和竞争力，所以完善法律服务是营商环境的重要内容——由重要性推重要性，没有负面现象。\n提速：先给题干贴标签（问题—危害—对策），再找同样从负面现象出发、落到对策的选项。',
 val='“问题—危害—对策”结构识别，广东卷常见的政论式论证结构题；A、C、D都没有负面现象这一起点。',
 flags=['扫描件解析出图核对'],
 notes='解析原文（扫描件第10—11页）：“题干逻辑：给出一个负面的现象，说明负面现象会产生的影响，由此得出应该改变负面现象的结论”，B当选，A、C、D“并没有提到负面现象及其影响”。与编者一致。题干原卷跨第8—9页。编者难度估计：中。'),

dict(id='PD3B-045', order=10, topic='论证结构相似', key='GDXD2019SW-50',
 stem='如果全球变暖的趋势持续下去，各类粮食作物的害虫会变得更为活跃，而对于绝大多数害虫而言，温带地区是其主要栖息地，因此在全球变暖背景下，温带粮食产区受到的影响将会更为严重。\n下列选项中，与上述论证在结构上最为相似的是（　）。',
 options={'A': '液氮可能造成严重的皮肤和胃肠道损伤。分子料理的流行增加了液氮的使用量，因此可能有更多的人因液氮而受伤', 'B': '假药、劣药不仅危害患者，还会增加整个卫生系统的负担。低收入国家的假药、劣药十分猖獗，因此这些国家的卫生系统负担往往更重', 'C': '咖啡能够让参加考试的学生感觉更清醒，更有活力与自信，最终考试成绩也会有所提高。因此，建议考试前适当喝点咖啡', 'D': '紧张和焦虑会影响人们的记忆能力。在科研过程中，学者尤其需要依赖记忆能力，因此过度紧张和焦虑对学者们的科研能力影响较大'},
 src='D', chk='D', diff='H',
 sol='题干：全球变暖（作用源X）使害虫（中介M）更活跃；绝大多数害虫以温带为主要栖息地（M与对象T相联系）；所以温带粮食产区受影响更严重（X对T影响更大）。\nA：液氮造成损伤；分子料理流行增加液氮用量；所以可能更多人受伤——第二前提讲的是“X的用量增加”，结构不同。\nB：假药劣药危害患者、加重卫生系统负担（X加重M）；低收入国家假药劣药猖獗（与对象T相联系的是作用源X本身）；所以这些国家负担更重——与对象相联系的是作用源而非中介，结构不同。\nC：咖啡→清醒→自信→成绩提高，所以建议考前喝咖啡——因果链后给建议，结构不同。\nD：紧张焦虑影响记忆能力（X影响M）；学者尤其依赖记忆能力（M与T相联系）；所以紧张焦虑对学者科研能力影响较大（X对T影响更大）——同构，当选。\n程序核验：按“作用源—中介—对象”角色签名比对，唯一同形为D（verify_structure.log）。\n提速：看第二个前提把谁和“对象”联系起来——题干是“害虫（中介）—温带”，B是“假药（作用源）—低收入国家”，这是最常见的混淆。',
 val='三项角色比对：与“对象”相联系的是中介（害虫）而非作用源；B把作用源与对象相联系，是最强干扰。',
 flags=[],
 notes='解析原文（第13页）：“题干是从‘全球变暖’影响‘害虫’，‘害虫’影响‘温带粮食产区’……a影响b，b影响c，所以a影响c”；B“a影响b，c影响a，所以c影响b，与题干论证结构不一致”。与编者一致。同一题干在GDXD2020SW-18（前提题）中再次出现，本包未用该题，后续勿同日使用。编者难度估计：难。'),
]
